```dart
import 'package:http/http.dart' as http;
import 'dart:convert';

Future<void> chamarOpenAI(String mensagem) async {
  final response = await http.post(
    Uri.parse('https://seu-backend.com/chat'),
    headers: {'Content-Type': 'application/json'},
    body: jsonEncode({'texto': mensagem}),
  );

  if (response.statusCode == 200) {
    print('Resposta: ${jsonDecode(response.body)['resposta']}');
  } else {
    print('Erro: ${response.statusCode}');
  }
}
```

### Exemplo de backend (Node.js)
```javascript
