require('dotenv').config(); // Carrega .env

const app = express();
app.use(express.json());

app.post('/chat', async (req, res) => {
  const { texto } = req.body;

  // Valide a entrada
  if (!texto || texto.length > 1000) {
    return res.status(400).send('Entrada inválida');
  }

  try {
    const response = await axios.post(
      'https://api.openai.com/v1/chat/completions',
      {
        model: 'gpt-3.5-turbo',
        messages: [{ role: 'user', content: texto }],
        temperature: 0.7
      },
      {
        headers: {
          'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
          'Content-Type': 'application/json'
        }
      }
    );
    res.json({ resposta: response.data });
  } catch (error) {
    res.status(500).send('Erro no processamento');
  }
});

app.listen(3000, () => console.log('Backend rodando na porta 3000'));
```

### Resumo
- **Segurança do front-end**: Nunca coloque chaves de API no app.
- **Backend**: É o guardião da chave e da lógica.
- **HTTPS + Autenticação**: Protegem a comunicação e o acesso.
- **Validação**: Evita erros e abusos.

Seguindo essas práticas, você reduz significativamente o risco de vazamento de credenciais e garante que seu app e seus usuários estejam protegidos.

